-- Glorious Destiny — fiches des produits ajoutés le 11/11/2026, composition de « La gamme »
-- (d'après la photo d'ensemble fournie par la cliente) et publication de Silkening Mist
-- (confirmée par la cliente le 11/11/2026). Les fiches décrivent l'usage et les gestes ;
-- aucune promesse non vérifiable (durée de tenue chiffrée, composition, étanchéité…).

update public.produits set publie = true where slug = 'silkening-mist';

update public.produits set description = 'Faux cils en bande, effet fluffy wispy. Pack de 10 paires.',
  fiche = $f${"accroche": "Dix paires pour dix regards.", "histoire": "La bande la plus simple à poser, pour un regard fourni en quelques secondes. L'effet fluffy wispy mélange des fibres de longueurs différentes : le rendu est aérien, jamais figé. Le pack de 10 paires accompagne toutes vos sorties.", "benefices": ["Effet fluffy wispy, léger et aérien", "Pack de 10 paires", "Pose rapide, sans matériel professionnel", "Idéal pour débuter avec les faux cils"], "utilisation": ["Mesurez la bande sur votre paupière et recoupez l'extérieur si elle dépasse.", "Déposez un mince filet de colle à faux cils le long de la bande et attendez qu'elle devienne collante.", "Posez la bande au plus près de vos cils naturels, du centre vers les coins.", "Pressez doucement, puis unifiez avec un trait d'eye-liner si vous le souhaitez."], "conseil": "Courbez la bande entre vos doigts avant la pose : elle épouse mieux la forme de l'œil et les coins tiennent mieux.", "faq": [{"q": "Puis-je les réutiliser ?", "r": "Oui, avec soin : retirez-les doucement, ôtez la colle restante sur la bande et rangez-les dans leur plateau."}, {"q": "Quelle colle utiliser ?", "r": "Une colle prévue pour les faux cils en bande. Faites toujours un essai sur une petite zone de peau avant la première utilisation."}], "associes": ["cluster-lashes-box", "fluffy-lash-clusters-80d"]}$f$::jsonb
where slug = 'strip-lashes-fluffy-wispy';

update public.produits set fiche = $f${"accroche": "Du naturel au spectaculaire, dans la même boîte.", "histoire": "Une seule boîte, toutes les densités : de 30P pour un regard naturel à 100P pour un effet volume. Vous composez votre regard grappe par grappe et vous ajustez selon l'occasion.", "benefices": ["Densités de 30P à 100P dans une seule boîte", "Grappes à poser vous-même, à la maison", "Un regard sur mesure, du discret au volume", "Rangement en plateau, grappes faciles à saisir"], "utilisation": ["Démaquillez et séchez vos cils naturels.", "Appliquez la colle pour extension de cils sous vos cils naturels, par petites zones.", "Placez les grappes sous vos cils, en commençant par le coin externe.", "Pincez doucement les cils naturels et les grappes pour les unir."], "conseil": "Gardez les grappes les plus denses pour le coin externe et les plus légères vers le coin interne : le regard reste naturel.", "faq": [{"q": "Que veulent dire 30P à 100P ?", "r": "C'est la densité des grappes : plus le chiffre est élevé, plus la grappe est fournie."}, {"q": "Faut-il une colle spéciale ?", "r": "Oui, une colle pour extension de cils, comme notre Colle pour extension de cils."}], "associes": ["colle-extension-cils", "lash-extension-kit"]}$f$::jsonb
where slug = 'cluster-lashes-box';

update public.produits set fiche = $f${"accroche": "La longueur qui se remarque.", "histoire": "Des grappes fluffy de 12 à 26 mm, réparties sur deux plateaux : de quoi construire un regard très allongé, ou dégradé du coin interne au coin externe. Pour celles qui aiment les cils qui se voient.", "benefices": ["Longueurs de 12 à 26 mm", "Effet fluffy, volume léger", "Double plateau : de grandes quantités sous la main", "Idéal pour un effet allongé ou dégradé"], "utilisation": ["Choisissez les longueurs : courtes vers le coin interne, longues vers l'extérieur.", "Appliquez la colle pour extension de cils sous vos cils naturels, par petites zones.", "Posez les grappes en partant du coin externe.", "Pincez délicatement pour unir grappes et cils naturels."], "conseil": "Les longueurs de 22 à 26 mm sont spectaculaires : gardez-les pour le coin externe et une soirée.", "faq": [{"q": "Ces longueurs conviennent-elles à un look de tous les jours ?", "r": "Oui, en restant sur les longueurs de 12 à 16 mm. Les plus longues sont faites pour un regard plus marqué."}, {"q": "Faut-il une colle spéciale ?", "r": "Oui, une colle pour extension de cils, comme notre Colle pour extension de cils."}], "associes": ["colle-extension-cils", "fluffy-lash-clusters-200d"]}$f$::jsonb
where slug = 'fluffy-lash-clusters-12-26';

update public.produits set fiche = $f${"accroche": "Le volume maximal.", "histoire": "200D, c'est la densité la plus fournie de notre gamme de grappes. Avec des longueurs de 14 à 24 mm, le regard devient intense et dramatique, en quelques grappes seulement.", "benefices": ["Densité 200D : volume maximal", "Longueurs de 14 à 24 mm", "Effet fluffy", "Un regard intense avec peu de grappes"], "utilisation": ["Démaquillez et séchez vos cils naturels.", "Appliquez la colle pour extension de cils sous vos cils naturels, par petites zones.", "Placez les grappes en partant du coin externe, en les espaçant légèrement.", "Pincez doucement pour unir grappes et cils naturels."], "conseil": "Avec cette densité, inutile de serrer les grappes : quelques-unes bien placées suffisent pour un regard très fourni.", "faq": [{"q": "Que signifie 200D ?", "r": "Le « D » indique la densité de la grappe : plus le chiffre est élevé, plus le volume est important. 200D est notre plus fournie."}, {"q": "Faut-il une colle spéciale ?", "r": "Oui, une colle pour extension de cils, comme notre Colle pour extension de cils."}], "associes": ["colle-extension-cils", "fluffy-lash-clusters-12-26"]}$f$::jsonb
where slug = 'fluffy-lash-clusters-200d';

