update public.produits set fiche = $f${"accroche": "La pose de vos extensions commence ici.", "histoire": "Une belle pose de cils dépend d'abord de la colle. Celle-ci est faite pour les extensions et les grappes : vous l'appliquez en fine couche, sous vos cils naturels, puis vous posez et pincez.", "benefices": ["Pour les extensions et les grappes de cils", "Application en fine couche, précise", "Compatible avec toutes nos grappes", "Pour la pose à la maison comme au salon"], "utilisation": ["Démaquillez et séchez vos cils naturels.", "Déposez une fine couche de colle sous vos cils naturels, par petites zones.", "Laissez-la devenir légèrement collante, puis posez les grappes.", "Pincez délicatement et laissez sécher avant de toucher."], "conseil": "Peu de colle, bien répartie : c'est ce qui donne une pose propre, sans paquets.", "faq": [{"q": "J'ai les yeux sensibles, je peux l'utiliser ?", "r": "Faites d'abord un essai sur une petite zone de peau 24 heures avant. Évitez tout contact avec l'œil ; en cas de contact, rincez abondamment à l'eau claire."}, {"q": "Comment la conserver ?", "r": "Refermez bien le flacon après chaque utilisation et rangez-le à l'abri de la chaleur."}], "associes": ["lash-extension-kit", "cluster-lashes-box"]}$f$::jsonb
where slug = 'colle-extension-cils';

update public.produits set fiche = $f${"accroche": "Une fixation en gel, pour une pose précise.", "histoire": "La texture gel liquide se dépose exactement là où vous la voulez, le long de la ligne frontale. Le flacon à embout fin permet un tracé régulier pour une pose propre de votre perruque.", "benefices": ["Texture gel liquide, facile à étaler", "Flacon à embout fin pour un tracé précis", "Pour la pose de perruque lace", "Complète Lace Glue et Lace Melting Spray"], "utilisation": ["Nettoyez la peau du front (sans crème ni huile) et laissez sécher.", "Déposez une fine couche le long de la ligne frontale.", "Attendez qu'elle devienne légèrement collante.", "Posez la dentelle et pressez de l'avant vers l'arrière."], "conseil": "Comme pour toute fixation, plusieurs couches fines tiennent mieux qu'une seule couche épaisse.", "faq": [{"q": "Comment la retirer ?", "r": "Avec Lace Glue Remover Spray : vaporisez sur les bords, laissez agir, puis décollez doucement."}, {"q": "J'ai la peau sensible ?", "r": "Faites d'abord un essai sur une petite zone, derrière l'oreille, 24 heures avant la pose."}], "associes": ["lace-glue-remover-spray", "lace-melting-spray"]}$f$::jsonb
where slug = 'glue-liquid-gel';

update public.produits set fiche = $f${"accroche": "Le coiffage qui reste en place.", "histoire": "Chignon lisse, queue de cheval tirée, contours nets : Hair Styling Gel donne de la tenue à votre coiffure. Le pot se travaille aux doigts, à la brosse ou au peigne.", "benefices": ["Tenue pour chignons, queues de cheval et contours", "Pot pratique, à la maison comme au salon", "Se travaille aux doigts, à la brosse ou au peigne", "Fini net et lisse"], "utilisation": ["Prélevez une petite quantité de gel.", "Répartissez-la sur les cheveux, mèche par mèche.", "Lissez à la brosse ou au peigne dans la direction voulue.", "Attachez ou fixez la coiffure, puis laissez sécher."], "conseil": "Pour un fini encore plus lisse, nouez un foulard en satin quelques minutes après le coiffage.", "faq": [{"q": "Quelle différence avec Braid Gel ?", "r": "Braid Gel est pensé pour les tresses, locks et twists ; Hair Styling Gel pour coiffer et plaquer : chignons, queues de cheval, contours."}, {"q": "Faut-il en mettre beaucoup ?", "r": "Non : commencez par une petite quantité et ajoutez-en si besoin."}], "associes": ["wax-stick", "braid-gel"]}$f$::jsonb
