where slug = 'silkening-mist';

update public.produits set description = 'Les produits Glorious Destiny réunis en un seul achat, comme sur la photo : Lace Glue (2 formats), Lace Melting Spray (2 formats), Wax Stick (2 formats), Glue Liquid Gel, Lace Glue Remover Spray, Silkening Mist et Hair Styling Gel.',
  fiche = $f${"accroche": "Toute la gamme, en un seul geste.", "histoire": "De la pose au retrait, en passant par le coiffage : La gamme réunit les produits Glorious Destiny présentés sur la photo. Tout ce qu'il faut pour poser, fondre, coiffer et retirer, sans rien oublier.", "benefices": ["Lace Glue (2 formats) et Glue Liquid Gel pour la pose", "Lace Melting Spray (2 formats) pour une lisière invisible", "Wax Stick (2 formats), Hair Styling Gel et Silkening Mist pour le coiffage", "Lace Glue Remover Spray pour un retrait en douceur"], "utilisation": ["Pose : Lace Glue ou Glue Liquid Gel le long de la ligne frontale.", "Finition de la lisière : Lace Melting Spray sous un bandeau élastique.", "Coiffage : Hair Styling Gel, Wax Stick pour les contours, Silkening Mist en touche finale.", "Retrait : Lace Glue Remover Spray, puis laissez agir avant de décoller."], "conseil": "Rangez La gamme dans l'ordre du rituel : pose, finition, coiffage, retrait. Vous gagnez du temps à chaque pose.", "faq": [{"q": "Que contient exactement La gamme ?", "r": "Les produits de la photo : Lace Glue (2 formats), Lace Melting Spray (2 formats), Wax Stick (2 formats), Glue Liquid Gel, Lace Glue Remover Spray, Silkening Mist et Hair Styling Gel."}, {"q": "Pourquoi choisir La gamme ?", "r": "Pour avoir tous les produits du rituel en un seul achat, de la pose au retrait."}], "associes": ["lace-glue", "lace-melting-spray"]}$f$::jsonb
where slug = 'la-gamme';
